<template>
  <div class="main">
    <div
      class="top-wrap-marketing"
      :class="{ tableHide: marketingData.tableMax }"
    >
      <div
        class="echart-box"
        ref="step"
        v-show="task.Status === 4 || task.Status === 5 || task.Status === 6"
      >
        <transition-group
          name="list"
          style="width: 100%; height: 100%; display: flex"
        >
          <div
            class="step-option"
            :class="{ 'foreach-icon-box': index % 9 === 0 && index !== 0 }"
            v-for="(item, index) of MarketingStep"
            :key="item.Time + index"
          >
            <div class="step-contain" :class="item.class">
              <div class="step-icon-box">
                <i class="el-icon-s-flag"></i>
              </div>
              <div>
                <div class="step-desc two-row">{{ item.LogTxt }}</div>
              </div>
              <div
                class="marketing-step-status marketing-success"
                v-show="item.Code === 0"
              >
                <!-- 成功 -->
                {{ $t("common.success") }}
              </div>
              <div
                class="marketing-step-status marketing-fail"
                v-show="item.Code !== 0"
              >
                <!-- 失败 -->
                {{ $t("common.fail") }}
              </div>
            </div>
          </div>
        </transition-group>
      </div>

      <div
        class="spider-box"
        id="spiderBox"
        v-show="task.Status !== 4 && task.Status !== 5 && task.Status !== 6"
      ></div>

      <div class="action-box">
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-envelope-o"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }"
              >Email</span
            >
          </div>
          <div class="action-option-right">
            <el-switch
              active-color="#51CCEE"
              v-model="marketingData.taskIsOpen.IsOpenEmail"
              :width="43"
              @click.native="handleDutyChange('IsOpenEmail')"
            ></el-switch>
          </div>
        </div>
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="el-icon-s-marketing"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }">{{
              $lang("marketing.reMarketing", "再营销")
            }}</span>
          </div>
          <div class="action-option-right">
            <el-switch
              active-color="#51CCEE"
              v-model="marketingData.taskIsOpen.IsReMarketing"
              :width="43"
              @click.native="handleDutyChange('IsReMarketing')"
            ></el-switch>
          </div>
        </div>
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-linkedin-square"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }"
              >LinkedIn</span
            >
          </div>
          <div class="action-option-right">
            <el-switch
              active-color="#51CCEE"
              v-model="marketingData.taskIsOpen.IsOpenLinkedIn"
              :width="43"
              @click.native="handleDutyChange('IsOpenLinkedIn')"
            ></el-switch>
          </div>
        </div>
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-files-o"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }">
              <!-- 日任务指标 -->
              {{ $t("marketing.dailyTask") }}
            </span>
          </div>
          <div class="action-option-right">
            {{ getterTaskIndicators.TaskIndicators }}
          </div>
        </div>
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-twitter-square"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }"
              >Twitter</span
            >
          </div>
          <div class="action-option-right">
            <el-switch
              active-color="#51CCEE"
              :width="43"
              v-model="marketingData.taskIsOpen.IsOpenTwitter"
              @click.native="handleDutyChange('IsOpenTwitter')"
            ></el-switch>
          </div>
        </div>
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-line-chart"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }">
              <!-- 已完成 -->
              {{ $t("common.completed") }}
            </span>
          </div>
          <div class="action-option-right">
            {{ marketingData.completedNumber }}
          </div>
        </div>

        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-facebook-official"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }"
              >FaceBook</span
            >
          </div>
          <div class="action-option-right">
            <el-switch
              active-color="#51CCEE"
              :width="43"
              v-model="marketingData.taskIsOpen.IsOpenFaceBook"
              @click.native="handleDutyChange('IsOpenFaceBook')"
            ></el-switch>
          </div>
        </div>

        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-random"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }">
              <!-- 排队中 -->
              {{ $t("marketing.inLine") }}
            </span>
          </div>
          <div class="action-option-right">
            {{ getterTaskIndicators.SurplusIndex }}
          </div>
        </div>
        <div class="action-option-box">
          <div class="action-option-left">
            <i class="fa fa-instagram"></i>
            <span :class="{ 'action-option-en': $i18n.locale === 'en' }"
              >Instagram</span
            >
          </div>
          <div class="action-option-right">
            <el-switch
              active-color="#51CCEE"
              v-model="marketingData.taskIsOpen.IsOpenInstagram"
              :width="43"
              @click.native="handleDutyChange('IsOpenInstagram')"
            ></el-switch>
          </div>
        </div>

        <div class="action-option-btn-box">
          <button class="acceleration-btn" @click="openSettingDialog">
            <i class="el-icon-setting"></i>
            <!-- 营销设置 -->
            {{ $t("marketing.marketingSettingBtn") }}
          </button>
        </div>
      </div>
    </div>

    <div class="middle-wrap" :class="{ tableHide: marketingData.tableMax }">
      <div class="nav-wrap">
        <el-tabs v-model="tab.activeName">
          <el-tab-pane name="log">
            <div slot="label">
              <!-- 运行日志 -->
              {{ $t("marketing.runLog") }}
            </div>
          </el-tab-pane>
          <el-tab-pane name="table">
            <div
              slot="label"
              style="position: relative"
              :style="{
                width: `${
                  (String(marketingData.page.total).length - 1) * 10 + 50
                }px`,
              }"
            >
              <!-- 数据 -->
              {{ $t("marketing.data") }}
              <span style="position: absolute; left: 30px"
                >({{ marketingData.page.total }})</span
              >
            </div>
          </el-tab-pane>
        </el-tabs>
        <div class="check-web" @click="goCheckWeb">
          <!-- 查看网页 -->
          {{ $t("marketing.viewWeb") }}
        </div>
      </div>
      <div class="start-stop-btn">
        <el-button
          type="danger"
          plain
          @click="stopCrawl"
          :disabled="
            (task.Status !== 1 && task.Status !== 4 && task.Status !== 7) ||
            marketingData.stopping
          "
        >
          <i class="fa fa-pause"></i>
          <span class="start-stop-btn-name">
            <!-- 暂停 -->
            {{ $t("common.stop") }}
          </span>
        </el-button>
        <el-button
          type="primary"
          plain
          @click="startCrawl"
          v-show="
            task.Status === 0 ||
            task.Status === 2 ||
            task.Status === 3 ||
            task.Status === 8
          "
        >
          <i class="fa fa-play"></i>
          <span class="start-stop-btn-name">
            <!-- 开始采集 -->
            {{ $t("marketing.startCrawl") }}
          </span>
        </el-button>
        <el-button
          type="primary"
          plain
          disabled
          v-show="task.Status === 1 || task.Status === 7"
        >
          <i class="el-icon-loading"></i>
          <span class="start-stop-btn-name">
            <!-- 采集中 -->
            {{ $t("marketing.crawlling") }}
          </span>
        </el-button>
        <el-button
          type="primary"
          plain
          @click="startCrawl"
          v-show="task.Status === 5 || task.Status === 9"
        >
          <i class="fa fa-play"></i>
          <span class="start-stop-btn-name">
            <!-- 开始营销 -->
            {{ $t("marketing.startMarketing") }}
          </span>
        </el-button>
        <el-button
          type="primary"
          plain
          @click="startCrawl"
          v-show="task.Status === 6"
        >
          <i class="fa fa-play"></i>
          <span class="start-stop-btn-name">
            <!-- 重新营销 -->
            {{ $t("marketing.remarketing") }}
          </span>
        </el-button>
        <el-button type="primary" plain disabled v-show="task.Status === 4">
          <i class="el-icon-loading"></i>
          <span class="start-stop-btn-name">
            <!-- 营销中 -->
            {{ $t("marketing.marketingin") }}
          </span>
        </el-button>
      </div>
      <div class="social-status-box">
        <div class="social-status-option">
          <div class="social-status social-fail"></div>
          <div class="social-status-tip">
            <!-- 放弃 -->
            {{ $t("marketing.giveUp") }}
          </div>
        </div>
        <div class="social-status-option">
          <div class="social-status social-success"></div>
          <div class="social-status-tip">
            <!-- 已执行 -->
            {{ $t("marketing.executed") }}
          </div>
        </div>
        <div class="social-status-option">
          <div class="social-status social-before"></div>
          <div class="social-status-tip">
            <!-- 未执行 -->
            {{ $t("marketing.unexecuted") }}
          </div>
        </div>
      </div>
    </div>
    <div class="change-table">
      <i
        class="change-table-size"
        :class="{
          'el-icon-arrow-up': !marketingData.tableMax,
          'el-icon-arrow-down': marketingData.tableMax,
        }"
        @click="marketingData.tableMax = !marketingData.tableMax"
      ></i>
    </div>
    <div class="bottom-wrap">
      <base-layout v-show="tab.activeName === 'table'">
        <div style="height: 100%">
          <el-table
            :data="tableData"
            style="width: 100%"
            height="100%"
            v-loading="marketingData.tableLoading"
            :element-loading-text="marketingData.tableLoadingText"
            element-loading-spinner="el-icon-loading"
            element-loading-background="rgb(255,255,255)"
            :header-cell-style="{ background: '#F5F5F5', color: '#606266' }"
            @selection-change="handleSelectionChange"
            ref="table"
          >
            <el-table-column type="selection" width="50"></el-table-column>
            <el-table-column
              :label="$lang('marketing.companyWeb', '公司网站')"
              min-width="200"
            >
              <template slot-scope="scope">
                <!-- {{scope.row}} -->
                <div class="table-web-wrap">
                  <div class="table-contact-obj">
                    <div class="table-contact-icon">
                      <i class="iconfont icon-lianxiren"></i>
                    </div>
                    <div class="table-contant-number">
                      {{
                        scope.row.Email.length +
                        scope.row.FaceBook.length +
                        scope.row.LinkedIn.length +
                        scope.row.Twitter.length +
                        scope.row.Instagram.length
                      }}
                    </div>
                    <div class="table-contact-status">
                      <el-tooltip
                        effect="light"
                        :content="scope.row.Status | filterRowStatus(that)"
                        placement="bottom-start"
                      >
                        <div
                          class="one-row"
                          :class="{
                            'table-status-start': scope.row.Status === 0,
                            'table-status-loading': scope.row.Status === 1,
                            'table-status-complete': scope.row.Status === 2,
                            'table-status-stop':
                              scope.row.Status === 3 || scope.row.Status === 7,
                            'table-crawl-status-start': scope.row.Status === 4,
                            'table-crawl-status-loading':
                              scope.row.Status === 5,
                            'table-crawl-status-complete':
                              scope.row.Status === 6,
                          }"
                        >
                          <i
                            :class="{
                              iconfont: scope.row.Status !== 1,
                              'icon-weikaishi': scope.row.Status === 0,
                              'el-icon-loading': scope.row.Status === 1,
                              'icon-yizhihang': scope.row.Status === 2,
                              'icon-stop-circle':
                                scope.row.Status === 3 ||
                                scope.row.Status === 7,
                              'icon-zhihang': scope.row.Status === 4,
                              'icon-shenwa': scope.row.Status === 5,
                              'icon-yiwancheng': scope.row.Status === 6,
                            }"
                          ></i>
                          {{ scope.row.Status | filterRowStatus(that) }}
                        </div>
                      </el-tooltip>
                    </div>
                  </div>

                  <div class="table-info-box">
                    <div>
                      <div
                        @click="goUrl(scope.row.Url)"
                        class="table-web-tit one-row"
                      >
                        {{ scope.row.Title }}
                      </div>
                      <div
                        @click="goUrl(scope.row.Url)"
                        class="table-web-url one-row"
                      >
                        <span>{{ scope.row.Url }}</span>
                      </div>
                      <div class="table-web-desc two-row">
                        {{ scope.row.Description }}
                      </div>
                    </div>
                  </div>
                </div>
              </template>
            </el-table-column>
            <el-table-column label="Email">
              <template slot-scope="scope">
                <div class="table-social-wrap">
                  <div
                    class="table-social-option"
                    v-for="(item, index) in scope.row.Email"
                    :key="index"
                  >
                    <template v-if="index < 3">
                      <div
                        class="table-social-status"
                        :class="{
                          'social-before': item.Status === 0,
                          'social-success': item.Status === 1,
                          'social-fail': item.Status === 2,
                        }"
                      ></div>
                      <div class="table-social-info one-row">
                        {{ item.Data }}
                      </div>
                    </template>
                  </div>
                  <div class="no-data-box" v-if="scope.row.Email.length === 0">
                    <i class="iconfont icon-zanwushuju no-data-icon"></i>
                    <div>
                      <!-- 暂无数据 -->
                      {{ $t("marketing.noData") }}
                    </div>
                  </div>
                  <div class="table-more-box" v-if="scope.row.Email.length > 0">
                    <i
                      class="iconfont icon-more table-social-more"
                      @click="openSocialPanel(scope.row, 'Email')"
                    ></i>
                    <span class="table-num">{{ scope.row.Email.length }}</span>
                  </div>
                </div>
              </template>
            </el-table-column>

            <el-table-column label="FaceBook">
              <template slot-scope="scope">
                <div class="table-social-wrap">
                  <div
                    class="table-social-option"
                    v-for="(item, index) in scope.row.FaceBook"
                    :key="index"
                  >
                    <template v-if="index < 3">
                      <div
                        class="table-social-status"
                        :class="{
                          'social-before': item.Status === 0,
                          'social-success': item.Status === 1,
                          'social-fail': item.Status === 2,
                        }"
                      ></div>
                      <div class="table-social-info one-row">
                        {{ item.Data }}
                      </div>
                    </template>
                  </div>
                  <div
                    class="no-data-box"
                    v-if="scope.row.FaceBook.length === 0"
                  >
                    <i class="iconfont icon-zanwushuju no-data-icon"></i>
                    <div>
                      <!-- 暂无数据 -->
                      {{ $t("marketing.noData") }}
                    </div>
                  </div>
                  <div
                    class="table-more-box"
                    v-if="scope.row.FaceBook.length > 0"
                  >
                    <i
                      class="iconfont icon-more table-social-more"
                      @click="openSocialPanel(scope.row, 'FaceBook')"
                    ></i>
                    <span class="table-num">{{
                      scope.row.FaceBook.length
                    }}</span>
                  </div>
                </div>
              </template>
            </el-table-column>
            <el-table-column label="LinkedIn">
              <template slot-scope="scope">
                <div class="table-social-wrap">
                  <div
                    class="table-social-option"
                    v-for="(item, index) in scope.row.LinkedIn"
                    :key="index"
                  >
                    <template v-if="index < 3">
                      <div
                        class="table-social-status"
                        :class="{
                          'social-before': item.Status === 0,
                          'social-success': item.Status === 1,
                          'social-fail': item.Status === 2,
                        }"
                      ></div>
                      <div class="table-social-info one-row">
                        {{ item.Data }}
                      </div>
                    </template>
                  </div>
                  <div
                    class="no-data-box"
                    v-if="scope.row.LinkedIn.length === 0"
                  >
                    <i class="iconfont icon-zanwushuju no-data-icon"></i>
                    <div>
                      <!-- 暂无数据 -->
                      {{ $t("marketing.noData") }}
                    </div>
                  </div>
                  <div
                    class="table-more-box"
                    v-if="scope.row.LinkedIn.length > 0"
                  >
                    <i
                      class="iconfont icon-more table-social-more"
                      @click="openSocialPanel(scope.row, 'LinkedIn')"
                    ></i>
                    <span class="table-num">{{
                      scope.row.LinkedIn.length
                    }}</span>
                  </div>
                </div>
              </template>
            </el-table-column>
            <el-table-column label="Twitter">
              <template slot-scope="scope">
                <div class="table-social-wrap">
                  <div
                    class="table-social-option"
                    v-for="(item, index) in scope.row.Twitter"
                    :key="index"
                  >
                    <template v-if="index < 3">
                      <div
                        class="table-social-status"
                        :class="{
                          'social-before': item.Status === 0,
                          'social-success': item.Status === 1,
                          'social-fail': item.Status === 2,
                        }"
                      ></div>
                      <div class="table-social-info one-row">
                        {{ item.Data }}
                      </div>
                    </template>
                  </div>
                  <div
                    class="no-data-box"
                    v-if="scope.row.Twitter.length === 0"
                  >
                    <i class="iconfont icon-zanwushuju no-data-icon"></i>
                    <div>
                      <!-- 暂无数据 -->
                      {{ $t("marketing.noData") }}
                    </div>
                  </div>
                  <div
                    class="table-more-box"
                    v-if="scope.row.Twitter.length > 0"
                  >
                    <i
                      class="iconfont icon-more table-social-more"
                      @click="openSocialPanel(scope.row, 'Twitter')"
                    ></i>
                    <span class="table-num">{{
                      scope.row.Twitter.length
                    }}</span>
                  </div>
                </div>
              </template>
            </el-table-column>
            <el-table-column label="Instagram">
              <template slot-scope="scope">
                <div class="table-social-wrap">
                  <div
                    class="table-social-option"
                    v-for="(item, index) in scope.row.Instagram"
                    :key="index"
                  >
                    <template v-if="index < 3">
                      <div
                        class="table-social-status"
                        :class="{
                          'social-before': item.Status === 0,
                          'social-success': item.Status === 1,
                          'social-fail': item.Status === 2,
                        }"
                      ></div>
                      <div class="table-social-info one-row">
                        {{ item.Data }}
                      </div>
                    </template>
                  </div>
                  <div
                    class="no-data-box"
                    v-if="scope.row.Instagram.length === 0"
                  >
                    <i class="iconfont icon-zanwushuju no-data-icon"></i>
                    <div>
                      <!-- 暂无数据 -->
                      {{ $t("marketing.noData") }}
                    </div>
                  </div>
                  <div
                    class="table-more-box"
                    v-if="scope.row.Instagram.length > 0"
                  >
                    <i
                      class="iconfont icon-more table-social-more"
                      @click="openSocialPanel(scope.row, 'Instagram')"
                    ></i>
                    <span class="table-num">{{
                      scope.row.Instagram.length
                    }}</span>
                  </div>
                </div>
              </template>
            </el-table-column>
          </el-table>
        </div>

        <div slot="footer" class="table-page-box">
          <el-pagination
            small
            layout="slot, prev, pager, next"
            :page-size="marketingData.page.num"
            :total="marketingData.page.total"
            :current-page.sync="marketingData.page.page"
            @current-change="currentPageChange"
          >
            <div style="float: left" class="delete-box-box">
              <el-button plain type="primary" @click="handleDeleteOption">
                <!-- 删除 -->
                {{ $t("common.delete") }}
              </el-button>
            </div>
          </el-pagination>
        </div>
      </base-layout>
      <div class="log-wrap" v-show="tab.activeName === 'log'">
        <div class="log-box" ref="log">
          <div
            class="log-option one-row"
            v-for="(item, index) of marketingData.logData"
            :key="index"
          >
            [
            <span>{{ item.TxtCreateTime }}</span
            >]:
            <span>{{ item.LogTxt }}</span>
          </div>
        </div>
        <div class="delete-log-btn">
          <el-button size="mini" type="primary" @click="handleDelLog">
            <!-- 删除 -->
            {{ $t("common.delete") }}
          </el-button>
        </div>
      </div>
    </div>

    <transition name="el-zoom-in-center">
      <!-- 营销设置 -->
      <wml-dialog
        :title="$t('marketing.marketingSettingTitle')"
        width="800px"
        v-if="marketingData.dialogShow"
        :visible.sync="marketingData.dialogShow"
        customClass="marketing-setting-dialog"
      >
        <!-- 加载设置中 -->
        <set-dialog
          v-loading="settingData.loading"
          :element-loading-text="$t('marketing.marketingSettingLoading')"
          element-loading-spinner="el-icon-loading"
          element-loading-background="rgb(255, 255, 255)"
        ></set-dialog>
      </wml-dialog>
    </transition>
    <wml-dialog
      :title="marketingData.socialDialog.title"
      width="800px"
      :visible.sync="marketingData.socialDialog.show"
      customClass="social-panel-dialog"
    >
      <div style="width: 100%; height: 100%">
        <div class="social-wrap">
          <div
            class="social-option"
            v-for="(item, index) of marketingData.socialDialog.panelData"
            :key="index"
          >
            <div class="social-content">
              <div
                style="
                  width: 7px;
                  height: 7px;
                  border-radius: 50%;
                  margin-right: 10px;
                  flex-shrink: 0;
                "
                :class="{
                  'social-before': item.Status === 0,
                  'social-success': item.Status === 1,
                  'social-fail': item.Status === 2,
                }"
              ></div>
              <div
                v-if="marketingData.socialDialog.title === 'Email'"
                class="two-row"
                :title="item.Data"
              >
                {{ item.Data }}
              </div>
              <div
                v-if="marketingData.socialDialog.title !== 'Email'"
                class="social-goUrl two-row"
                :title="item.Data"
                @click="goUrl(item.Data)"
              >
                {{ item.Data }}
              </div>
            </div>
            <div class="copy-btn-box">
              <span @click="copy(item.Data)">
                <!-- 复制 -->
                {{ $t("common.copyBtn") }}
              </span>
            </div>
            <el-radio-group v-model="item.Status" size="mini">
              <el-radio :label="0">
                <!-- 未执行 -->
                {{ $t("marketing.unexecuted") }}
              </el-radio>
              <el-radio :label="1">
                <!-- 已执行 -->
                {{ $t("marketing.executed") }}
              </el-radio>
              <el-radio :label="2">
                <!-- 放弃 -->
                {{ $t("marketing.giveUp") }}
              </el-radio>
            </el-radio-group>
          </div>
        </div>
        <div class="social-btn-box">
          <el-button size="mini" type="primary" @click="doSaveSocial">
            <!-- 保存 -->
            {{ $t("common.saveBtn") }}
          </el-button>
          <el-button
            size="mini"
            type="danger"
            plain
            @click="marketingData.socialDialog.show = false"
          >
            <!-- 取消 -->
            {{ $t("common.cancelBtn") }}
          </el-button>
        </div>
      </div>
    </wml-dialog>
    <wml-dialog
      :title="marketingData.socialIdentityDialog.title"
      width="1000px"
      :visible.sync="marketingData.socialIdentityDialog.show"
      customClass="social-identity--dialog"
    >
      <div class="social-identity-dialog">
        <el-table
          :data="marketingData.socialIdentityDialog.data"
          stripe
          height="100%"
          style="width: 100%; height: 100%"
          ref="multipleTable"
          @row-click="rowClick"
        >
          <el-table-column type="expand">
            <template slot-scope="props">
              <div class="identity-table--expand">
                <div class="identity-expand-option">
                  <div class="identity-expand-title">昵称</div>
                  <div class="identity-expand-content">
                    {{ props.row.Nickname }}
                  </div>
                </div>
                <!-- <div class="identity-expand-option">
                  <div class="identity-expand-title">职务</div>
                  <div class="identity-expand-content">
                    <el-tag v-if="props.row.Post !== ''">
                      {{ props.row.Post }}
                    </el-tag>
                  </div>
                </div> -->
                <div class="identity-expand-option">
                  <div class="identity-expand-title">职务说明</div>
                  <div class="identity-expand-content">
                    {{ props.row.PostDecription }}
                  </div>
                </div>
                <div class="identity-expand-option">
                  <div class="identity-expand-title">URL</div>
                  <div
                    class="identity-expand-content identity-url-style"
                    @click.stop="goUrl(props.row.Data)"
                  >
                    {{ props.row.Data }}
                  </div>
                  <div class="identity-expand-copy">
                    <i
                      class="el-icon-document-copy"
                      title="复制"
                      @click="copy(props.row.Data)"
                    ></i>
                  </div>
                </div>
                <div class="identity-expand-option">
                  <div class="identity-expand-title">地点</div>
                  <div class="identity-expand-content">
                    {{ props.row.Location }}
                  </div>
                </div>
              </div>
            </template>
          </el-table-column>
          <el-table-column width="50">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div
                  class="identity-status"
                  :class="{
                    'social-before': scope.row.Status === 0,
                    'social-success': scope.row.Status === 1,
                    'social-fail': scope.row.Status === 2,
                  }"
                ></div>
              </div>
            </template>
          </el-table-column>
          <el-table-column label="URL" width="230">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div
                  class="identity-URL two-row identity-url-style"
                  v-if="scope.row.Data !== ''"
                  @click.stop="goUrl(scope.row.Data)"
                >
                  {{ scope.row.Data }}
                </div>
                <div class="no-data-box" v-if="scope.row.Data === ''">
                  <i class="iconfont icon-zanwushuju no-data-icon"></i>
                  <div>
                    <!-- 暂无数据 -->
                    {{ $t("marketing.noData") }}
                  </div>
                </div>
              </div>
            </template>
          </el-table-column>
          <el-table-column label="昵称">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div
                  class="identity-nickname two-row"
                  v-if="scope.row.Nickname !== ''"
                >
                  {{ scope.row.Nickname }}
                </div>
                <div class="no-data-box" v-if="scope.row.Nickname === ''">
                  <i class="iconfont icon-zanwushuju no-data-icon"></i>
                  <div>
                    <!-- 暂无数据 -->
                    {{ $t("marketing.noData") }}
                  </div>
                </div>
              </div>
            </template>
          </el-table-column>
          <!-- <el-table-column label="职务">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div class="identity-position two-row">
                  {{ scope.row.Post }}
                </div>
              </div>
            </template>
          </el-table-column> -->
          <el-table-column label="职务说明">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div
                  class="identity-position two-row"
                  v-if="scope.row.PostDecription !== ''"
                >
                  {{ scope.row.PostDecription }}
                </div>
                <div class="no-data-box" v-if="scope.row.PostDecription === ''">
                  <i class="iconfont icon-zanwushuju no-data-icon"></i>
                  <div>
                    <!-- 暂无数据 -->
                    {{ $t("marketing.noData") }}
                  </div>
                </div>
              </div>
            </template>
          </el-table-column>
          <el-table-column label="地点" width="230">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div
                  class="identity-address two-row"
                  v-if="scope.row.Location !== ''"
                >
                  {{ scope.row.Location }}
                </div>
                <div class="no-data-box" v-if="scope.row.Location === ''">
                  <i class="iconfont icon-zanwushuju no-data-icon"></i>
                  <div>
                    <!-- 暂无数据 -->
                    {{ $t("marketing.noData") }}
                  </div>
                </div>
              </div>
            </template>
          </el-table-column>
          <el-table-column label="操作">
            <template slot-scope="scope">
              <div class="identity-table--row">
                <div class="identity-action">
                  <el-select
                    v-model="scope.row.Status"
                    size="mini"
                    @change="handleIdentityChange"
                  >
                    <el-option
                      v-for="(item, index) of identityStatusOption"
                      :key="index"
                      :label="item.label"
                      :value="item.value"
                    >
                    </el-option>
                  </el-select>
                </div>
              </div>
            </template>
          </el-table-column>
        </el-table>
      </div>
    </wml-dialog>
  </div>
</template>
<script>
import baseLayout from '@/home/common/baseLayout.vue'
import setDialog from '@/home/marketing/settingDialog/setDialog.vue'
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'marketingIndex',
  components: { baseLayout, setDialog },
  inject: ['reload'],
  data () {
    return {
      // 任务Id
      taskId: 0,
      echarts: '',
      marketingData: {},
      // tableDataDB: [],
      tableData: [],
      settingData: {},
      MarketingStep: [],
      task: {},
      tab: { activeName: 'table' },
      table: [],
      spiderOption: '',
      selectionData: [],
      that: this,
      resizeEchart: '',
      identityStatusOption: [
        {
          label: '未执行',
          value: 0
        },
        {
          label: '已执行',
          value: 1
        },
        {
          label: '放弃',
          value: 2
        }
      ],
      value: 0
    }
  },
  methods: {
    ...mapActions([
      'dispatchCrawMarketingData',
      'dispatchPushLogData',
      'dispatchUpdateMarketingData',
      'dispatchMarketingStep',
      'dispatchEchart',
      'dispatchDeleteMarketingData',
      'dispatchCurrentTaskId',
      'dispatchCompletedNumber',
      'dispatchContactSort',
      'dispatchContactReorder'
    ]),

    /**
   * @author: vince.Liang
   * @function: 数据初始化
   * @param none
   * @return:undefined
   */
    init () {
      this.taskId = Number(this.$route.params.id)
      // vuex没有当前任务id就注册监听事件
      if (this.judgeTaskId(this.taskId)) {
        // 监听任务数据插入
        this.$socket.on('insertTaskData' + this.taskId, e => {
          this.dispatchCrawMarketingData(e.detail)
          console.log('有没有执行')
          console.log(this.marketingData)
          if (this.marketingData.taskDataTable !== undefined && this.marketingData.taskDataTable.length !== undefined) {
            this.task.ContactNumber < this.marketingData.taskDataTable.length && this.task.ContactNumber++
          }
        })
        // 监听任务日志数据返回
        this.$socket.on('insertLog' + this.taskId, e => {
          this.dispatchPushLogData(e.detail)
        })
        // 监听修改任务数据返回
        this.$socket.on('updateTaskData' + this.taskId, e => {
          this.dispatchUpdateMarketingData(e.detail)
        })
        // 监听修改任务状态，主要在爬虫操作向营销操作过渡时触发
        // status  0(爬虫初始化),1(采集中),2(采集暂停),3(采集完成) 4(营销中) 5(营销暂停) 6(营销完成)
        this.$socket.on('updateTaskStatus' + this.taskId, e => {
          if (e.detail.Data.Status === 3) {
            this.$notify({
              title: this.$t('marketing.notifyTipTitle'),
              message: this.$t('marketing.initCrawlComplete'),
              type: 'success',
              duration: 0
            })
          }
          if (e.detail.Data.Status === 9 && this.task.Status !== 9) {
            this.$notify({
              title: this.$t('marketing.notifyTipTitle'),
              message: this.$t('marketing.depthCrawlComplete'),
              type: 'success',
              duration: 0
            })
          }
          if (e.detail.Data.Msg) {
            this.$WmlMsg(e.detail.Data.Msg, 'warning')
          }
          this.changeTaskStatus(e.detail.Data.TaskId, e.detail.Data.Status)
        })
        // 监听营销数据返回
        this.$socket.on('marketData' + this.taskId, e => {
          this.dispatchMarketingStep(e.detail)
        })
        // 监听图表数据返回
        this.$socket.on('updateChart' + this.taskId, e => {
          this.dispatchEchart(e.detail)
          if (e.detail.Data.TaskId === Number(this.$route.params.id)) {
            this.initEchart()
          }
        })
        // 删除数据
        this.$socket.on('deleteTaskData' + this.taskId, e => {
          this.dispatchDeleteMarketingData(e.detail)
        })
        // 监听任务完成数量返回
        this.$socket.on('taskCompleted' + this.taskId, e => {
          this.dispatchCompletedNumber(e.detail)
        })
        // 任务排序
        this.$socket.on('contactSort' + this.taskId, e => {
          this.dispatchContactSort(e.detail)
        })
        // 实时排序
        this.$socket.on('contactReorder' + this.taskId, e => {
          this.dispatchContactReorder(e.detail)
        })
      }

      this.marketingData = this.getterMarketingData(this.taskId)
      // this.tableDataDB = this.getterTaskTable(this.taskId)
      this.settingData = this.getterSettingData(this.taskId)
      this.task = this.getterTask(this.taskId)
      this.MarketingStep = this.getterMarketingStep(this.taskId)
      this.spiderOption = this.getterSpiderOption(this.taskId)
    },

    /**
     * @author: vince.Liang
     * @function: 打开设置弹窗并请求数据
     * @param none
     * @return:undefined
     */
    openSettingDialog () {
      this.settingData.loading = true
      this.SharpObj.getAllMationConfig(this.taskId, res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          Object.assign(this.settingData, res.Data)
          this.marketingData.dialogShow = true
          this.settingData.loading = false
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 点击切换当前页
     * @param none
     * @return:undefined
     */
    currentPageChange () {
      this.changePage()
    },

    /**
     * @author: vince.Liang
     * @function: 切换当前页替换vuex数据
     * @param none
     * @return:undefined
     */
    changePage () {
      this.selectionData = []
      let page = this.marketingData.page.page
      let num = this.marketingData.page.num
      this.tableData = this.marketingData.taskDataTable.slice((page - 1) * num, page * num)
    },

    /**
     * @author: vince.Liang
     * @function: 点击开始爬虫和营销
     * @param none
     * @return:undefined
     */
    startCrawl () {
      this.SharpObj.startTask(JSON.stringify(this.marketingData.taskIsOpen), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.changeTaskStatus(this.taskId, res.Data.Status)
          // 任务开始
          this.$WmlMsg(this.$t('marketing.taskStart'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 停止任务
     * @param none
     * @return:undefined
     */
    stopCrawl () {
      this.marketingData.stopping = true
      this.SharpObj.stopTask(this.taskId, res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.marketingData.stopping = false
          // 任务暂停成功
          this.$WmlMsg(this.$t('marketing.taskStopSuccess'))
          this.changeTaskStatus(this.taskId, res.Data.Status)
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: echart初始化
     * @param none
     * @return:undefined
     */
    initEchart () {
      // if (this.echarts) {
      //   this.$echarts.dispose(this.echarts)
      //   this.echarts = null
      // }
      this.echarts = this.$echarts.init(document.getElementById('spiderBox'))
      this.echarts.setOption(this.getterSpiderOption(this.$route.params.id))
    },

    /**
    * @author: vince.Liang
    * @function: 表格网址跳转外部页面
    * @param {String} url 跳转的网址
    * @return:undefined
    */
    goUrl (url) {
      window.open(url)
    },

    /**
     * @author: vince.Liang
     * @function: 复制功能
     * @param {String} text 需要复制的字符窜
     * @return: undefined
     */
    copy (text) {
      this.$copy(text)
    },

    /**
     * @author: vince.Liang
     * @function: 改变表格选中项触发的处理函数
     * @param {Array} selectionData 选中的数组
     * @return: undefined
     */
    handleSelectionChange (selectionData) {
      this.selectionData = selectionData
    },

    /**
     * @author: vince.Liang
     * @function: 删除表格选中项
     * @param none
     * @return:undefined
     */
    async handleDeleteOption () {
      if (this.selectionData.length === 0) {
        // 请先选择删除项
        this.$WmlMsg(this.$t('marketing.mustDeleteSelect'), 'warning')
        return
      }
      // 该操作将永久删除选中项目, 继续？
      let confirm = await this.$WmlConfirm(this.$t('marketing.confirmDeleteMessage'))
      if (!confirm) {
        return
      }
      // 删除中
      this.marketingData.tableLoadingText = this.$t('marketing.deleteing')
      this.marketingData.tableLoading = true
      let deleteIds = []
      for (let item of this.selectionData) {
        deleteIds.push(item.ContactId)
      }
      this.SharpObj.deleteContact(this.taskId, JSON.stringify(deleteIds), res => {
        res = JSON.parse(res)
        res.Data = JSON.parse(res.Data)
        if (res.Code === 0) {
          for (let item of res.Data) {
            for (let index = 0; index < this.marketingData.taskDataTable.length; index++) {
              if (this.marketingData.taskDataTable[index].ContactId === item) {
                this.marketingData.taskDataTable.splice(index, 1)
                break
              }
            }
          }
          this.marketingData.page.total = this.marketingData.page.total - res.Data.length
          if (Math.ceil(this.marketingData.page.total / this.marketingData.page.num) < this.marketingData.page.page) {
            this.marketingData.page.page = Math.ceil(this.marketingData.page.total / this.marketingData.page.num)
            this.changePage()
          }
          this.selectionData = []
          // 删除成功
          this.$WmlMsg(this.$t('marketing.deleteSuccess'))
          this.marketingData.tableLoading = false
        } else {
          this.$WmlMsg(res.Msg, 'warning')
          this.marketingData.tableLoading = false
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 打开社交操作面板
     * @param none
     * @return: undefined
     */
    openSocialPanel (row, type) {
      console.log(row)
      if (type === 'LinkedIn') {
        this.marketingData.socialIdentityDialog.title = type
        this.marketingData.socialIdentityDialog.show = true
        this.marketingData.socialIdentityDialog.data = row[type]
        return
      }
      this.marketingData.socialDialog.title = type
      this.marketingData.socialDialog.data = row[type]
      this.marketingData.socialDialog.panelData = JSON.parse(JSON.stringify(row[type]))
      this.marketingData.socialDialog.show = true
    },

    /**
     * @author: vince.Liang
     * @function: 保存社交方式状态弹窗的改变
     * @param none
     * @return: undefined
     */
    doSaveSocial () {
      this.SharpObj.updateContact(JSON.stringify(this.marketingData.socialDialog.panelData), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.marketingData.socialDialog.panelData.forEach((item, index) => {
            Object.assign(this.marketingData.socialDialog.data[index], item)
          })
          // 保存成功
          this.$WmlMsg(this.$t('marketing.saveSuccess'))
          this.marketingData.socialDialog.show = false
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 跳转查看网页
     * @param none
     * @return: undefined
     */
    goCheckWeb () {
      this.SharpObj.showBrowser(this.taskId, res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 判断是否允许切换任务开启状态
     * @param {String} type 当前需要切换的任务的标识
     * @return: undefined
     */
    handleDutyChange (type) {
      this.SharpObj.getTaskStatus(this.taskId, res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.marketingData.taskIsOpen[type] = !this.marketingData.taskIsOpen[type]
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 处理删除日志列表
     * @data: 2019-3-27
     * @param {none}
     * @return: undefined
     */
    async handleDelLog () {
      // 确定清除该任务的运行日志？
      let confirm = await this.$WmlConfirm(this.$t('marketing.confirmDeleteLog'))
      if (!confirm) { return }
      this.SharpObj.deleteTaskLog(this.taskId, res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.marketingData.logData.splice(0)
        this.$WmlMsg(this.$t('marketing.deleteSuccess'))
      })
    },
    /**
     * @author: vince.Liang
     * @function: 社交身份表格整行展示
     * @data: 2019-3-27
     * @param {type}
     * @return {type}
     */
    rowClick (row, column, event) {
      this.$refs.multipleTable.toggleRowExpansion(row)
    },
    handleIdentityChange () {
      this.SharpObj.updateContact(JSON.stringify(this.marketingData.socialIdentityDialog.data), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          // 保存成功
          this.$WmlMsg(this.$t('修改成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    }
  },
  mounted () {
    this.resizeEchart = this.$debounce(() => { this.echarts.resize() }, 100)
    window.addEventListener('resize', this.resizeEchart)
    let _that = this
    this.$bus.$on('resizeMarketingEchart', _ => {
      this.$nextTick(() => {
        _that.echarts.resize()
      })
    })
  },

  created () {
    this.init()
  },

  computed: {
    ...mapGetters([
      'getterMarketingData',
      'getterTaskTable',
      'judgeTaskId',
      'changeTaskStatus',
      'getterSettingData',
      'getterTask',
      'getterMarketingStep',
      'getterSpiderOption',
      'getterTaskIndicators'
    ])
  },
  watch: {
    'marketingData.taskDataTable': {
      handler (val) {
        if (this.tableData.length > val.length) {
          return
        }
        this.changePage()
      },
      deep: true
    },
    '$route' (to, from) {
      this.init()
      this.changePage()
      this.reload()
    },
    MarketingStep: {
      handler (val) {
        this.$nextTick(() => {
          this.$refs.step.scrollLeft = this.$refs.step.scrollWidth
        })
      }
    },
    'spiderOption.series.data': {
      handler (val) {
        this.initEchart()
      },
      deep: true
    }
  },
  filters: {
    filterRowStatus (status, that) {
      switch (status) {
        case 0:
          // return '未营销'

          return that.$t('marketing.marketingStatus0')
        case 1:
          // return '营销中'
          return that.$t('marketing.marketingStatus1')
        case 2:
          // return '已营销'
          return that.$t('marketing.marketingStatus2')
        case 3:
          // return '营销暂停'
          return that.$t('marketing.marketingStatus3')
        case 4:
          // return '未深挖'
          return that.$t('marketing.marketingStatus4')
        case 5:
          // return '深挖中'
          return that.$t('marketing.marketingStatus5')
        case 6:
          // return '已深挖'
          return that.$t('marketing.marketingStatus6')
        case 7:
          // return '深挖暂停'
          return that.$t('marketing.marketingStatus7')
      }
    }
  },
  beforeDestroy () {
    this.marketingData = null
    this.tableDataDB = null
    this.settingData = null
    this.task = null
    this.MarketingStep = null
    this.spiderOption = null
    if (this.echarts) {
      this.$echarts.dispose(this.echarts)
      this.echarts = null
    }
    window.removeEventListener('resize', this.resizeEchart)
    this.resizeEchart = null
    this.$bus.$off('resizeMarketingEchart')
    Object.assign(this.$data, this.$options.data())
