<script>
import { mapGetters } from 'vuex'
export default {
  name: 'setDialog',
  data () {
    return {
      checked: false,
      textarea: '',
      num: 10,
      settingData: '',
      checkAll: false,
      isIndeterminate: true,
      checkAllLinkIn: false,
      isIndeterminateLinkIn: true,
      DayOfWeekOption: [
        { key: 'Monday', label: this.$lang('common.monday', '星期一') },
        { key: 'Tuesday', label: this.$lang('common.tuesday', '星期二') },
        { key: 'Wednesday', label: this.$lang('common.wednesday', '星期三') },
        { key: 'Thursday', label: this.$lang('common.thursday', '星期四') },
        { key: 'Friday', label: this.$lang('common.friday', '星期五') },
        { key: 'Saturday', label: this.$lang('common.saturday', '星期六') },
        { key: 'Sunday', label: this.$lang('common.sunday', '星期日') }
      ],
      value: '',
      tabName: 'email'
    }
  },
  computed: {
    ...mapGetters(['getterSettingData'])
  },
  methods: {
    /**
     * @author: vince.Liang
     * @function: 初始化
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    init () {
      this.settingData = this.getterSettingData(Number(this.$route.params.id))
    },
    doSave (type) {
      this.SharpObj.setMationConfig(Number(this.$route.params.id), JSON.stringify(this.settingData[type]), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('marketing.saveSuccess', '保存成功'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    }
  },
  created () {
    this.init()
  },
